head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[checkbox > P > useCheckboxTitle]<br/>컴포넌트의 각 아이템 항목에 title 속성을 추가할지 여부를 설정합니다.",
    "validation" : [        
        "미설정 시 아이템 항목의 input 태그에 title 속성이 추가되고 라벨값으로 설정됩니다.",
        "false 설정 시 컴포넌트의 아이템 항목에 title 속성을 추가하지 않습니다.",
        "true 설정 시 아이템 항목의 input 태그에 title 속성이 추가되고 라벨값으로 설정됩니다.",
        "추가된 title 속성에는 컴포넌트의 title 속성값이 아닌 각 아이템의 라벨값이 설정됩니다.",   
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        title: "title",
        useCheckboxTitle: con_useCheckboxTitle.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    // target 생성
    $c.gcm.createBasicCheckBox(cList);
}



scwin.get_itemTitle_onclick = function (e) {
    // 'id'에 'target1'이 포함된 요소 선택
    let targetElements = document.querySelectorAll('[id*="target1"]');

    // 각 'target1' 요소 하위의 'w2radio_input' 클래스가 있는 input 태그 선택
    targetElements.forEach(element => {
        let inputs = element.querySelectorAll('input.w2checkbox_input');
        inputs.forEach((input, index) => {
            let title = input.title;
            wf_body_bottom.getObj("scwin").setReturnValue(`Input ${index + 1}의 title: ${title}`)
        });
    });	
};



scwin.btn_getTitle_onclick = function (e) {
    let rtn = '';

    rtn = target1.getTitle();
    wf_body_bottom.getObj("scwin").setReturnValue("getTitle : " + rtn);
};
